const http = require('http');

function makeRequest(cursor = 0) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify({
      status: 'todo',
      cursor: cursor
    });

    const options = {
      hostname: 'localhost',
      port: 3001,
      path: '/mcp/mcp__tracker__search_tasks',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        try {
          resolve(JSON.parse(data));
        } catch(e) {
          reject(e);
        }
      });
    });

    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

async function getAllTasks() {
  let allTasks = [];
  let cursor = 0;

  while (true) {
    const result = await makeRequest(cursor);
    console.log('Response:', JSON.stringify(result, null, 2));

    if (result.tasks) {
      allTasks = allTasks.concat(result.tasks);
    }

    if (!result.next_cursor) break;
    cursor = result.next_cursor;
  }

  console.log('Total todo tasks:', allTasks.length);
}

getAllTasks().catch(console.error);
"
